/* Role-based learning guides — Media Analytics/Marketing Science, SEO/GEO and CRM/Lifecycle.
 * Every case is SIMULATED unless an official demo source is explicitly named.
 */
var ROLE_GUIDES = ROLE_GUIDES || {};
function makeRoleChapter(concept,example,actions,practice,checks,terms){
 return {concept:concept,example:example,actions:actions,practice:practice,checks:checks,qaFocus:checks.map(function(x){return x[0];}),terms:terms};
}
ROLE_GUIDES.analytics = {
 scope:"Media Analytics / Marketing Science mengubah data advertising, ad server, web, commerce, and CRM menjadi evidence untuk keputusan. Core pathway berfokus pada data quality, KPI, dashboard, descriptive/diagnostic analysis, insight, and stakeholder communication. Pendalaman Marketing Science mencakup experimental design, incrementality, attribution limitations, regression, MMM, econometrics, and model validation. Jangan menganggap semua Media Analyst harus membangun MMM profesional; kedalaman statistik ditahapkan.",
 workflow:["<b>Frame the decision.</b> Mulai dari business question, audience, scope, outcome, guardrail, and decision owner.","<b>Acquire and validate data.</b> Periksa source, grain, taxonomy, timezone, joins, duplicates, missing values, consent, and freshness.","<b>Analyse with the right method.</b> Pisahkan descriptive, diagnostic, attribution, causal, and predictive questions.","<b>Communicate the evidence.</b> Bangun dashboard/memo yang menunjukkan finding, confidence, limitation, and action.","<b>Improve the measurement system.</b> Dokumentasikan data defects, experiment needs, methodology, and governance."],
 qa:["Descriptive menjawab apa yang terjadi; diagnostic mencari penjelasan yang didukung bukti; causal/experimental menilai dampak tambahan. Jangan menyimpulkan kausalitas dari korelasi dashboard.","Sebelum menggabungkan data, pastikan grain, primary key, timezone, currency, event definitions, attribution windows, deduplication, and filter logic. Join yang salah dapat menggandakan spend atau conversion.","Executive insight harus punya observation, evidence, interpretation, recommendation, impact, limitation, and next validation. Dashboard bukan pengganti reasoning."],
 glossary:[["Grain","Level detail satu baris dataset, misalnya campaign-day atau user-event."],["Taxonomy","Aturan penamaan dan klasifikasi event/campaign/channel."],["Data lineage","Jejak asal, transformasi, dan tujuan data."],["Descriptive analytics","Analisis tentang apa yang terjadi."],["Diagnostic analytics","Analisis untuk mencari faktor yang menjelaskan perubahan."],["Attribution","Aturan pemberian credit pada touchpoint; bukan bukti kausalitas."],["Incrementality","Tambahan outcome yang disebabkan aktivitas, di atas baseline."],["Confidence interval","Rentang ketidakpastian estimasi."],["MMM","Marketing Mix Modeling; pemodelan kontribusi channel/faktor ke outcome dari data historis."],["Model validation","Pemeriksaan apakah model bekerja pada data/keadaan yang relevan dan stabil."]],
 chapters:[
  makeRoleChapter("Analytics harus dimulai dari keputusan yang perlu dibuat, bukan dari data yang tersedia. Bedakan business question, metric question, diagnostic question, and action. Tetapkan population, unit of analysis, period, target, primary KPI, guardrail, and owner sebelum menarik data.","SIMULASI — revenue naik 12%, tetapi contribution margin turun. Pertanyaan yang benar bukan hanya 'channel mana yang menghasilkan revenue?', melainkan apakah product mix, discount, CAC, return rate, or channel mix menjelaskan perubahan margin.",["Ubah business issue menjadi pertanyaan yang falsifiable dan spesifik.","Tentukan outcome, metric definition, numerator/denominator, unit, period, segment, and owner.","Buat KPI tree dari business outcome ke driver dan diagnostic metrics.","Tulis decision rule: tindakan apa yang diambil bila metric naik/turun."],"Buat measurement brief satu halaman: business question, stakeholder, decision, population, KPI tree, definitions, source, time window, guardrail, assumptions, and next action.",[["Apa perbedaan business question dan metric question?","Business question menentukan keputusan bisnis; metric question menentukan ukuran/evidence untuk membantu keputusan tersebut. Contoh: 'mengapa margin turun?' adalah business question; 'bagaimana margin per order berubah menurut channel?' adalah metric question."],["Mengapa unit of analysis harus ditentukan sebelum mengambil data?","Karena campaign-day, session, user, order, dan impression tidak bisa dipertukarkan. Salah unit menyebabkan denominator atau agregasi salah."],["Apa fungsi guardrail metric?","Menjaga optimasi pada primary KPI tidak merusak kualitas, margin, customer experience, atau compliance."]],[["Business question","Pertanyaan yang mengarah ke keputusan."],["Primary KPI","Ukuran utama untuk mengevaluasi tujuan."],["Guardrail","Metrik pelindung kualitas atau risiko."]]),
  makeRoleChapter("Analyst perlu memahami sumber data dan model event sebelum membuat report. Platform ads, GA4, CM360, CRM, retailer, finance, and survey punya definisi, freshness, identity, and access yang berbeda. Taxonomy and documentation membuat angka dapat dibandingkan; data-quality audit memeriksa completeness, validity, consistency, uniqueness, timeliness, and accuracy.","SIMULASI — campaign naming berisi 'Meta_Awareness_Jan', 'META-awareness-jan', dan 'FB_awareness_01'. Dashboard memecah satu channel menjadi tiga label. Normalisasi taxonomy harus mempertahankan raw values dan menyimpan mapping table, bukan overwrite tanpa audit trail.",["Buat source inventory: owner, refresh cadence, fields, grain, access, and limitations.","Definisikan taxonomy untuk campaign, channel, objective, product, region, and event.","Audit duplicates, nulls, invalid values, outliers, timezone, currency, and naming drift.","Simpan raw layer, cleaned layer, transformation log, and QA outcome."],"Buat data-source map dan quality audit dengan minimal tiga sumber (ads export, GA4 demo, CRM synthetic). Tampilkan grain, keys, schema, null/duplicate checks, naming map, issues, severity, owner, and remediation.",[["Mengapa raw data sebaiknya tidak langsung ditimpa saat normalisasi?","Raw layer menjaga traceability dan memungkinkan perubahan mapping di-review. Cleaned layer harus punya transform log agar hasil dapat direproduksi."],["Apa risiko join campaign report dengan CRM tanpa memastikan grain?","Satu campaign row dapat cocok ke banyak CRM events/orders dan menggandakan spend/conversion. Aggregate or join dengan key/grain yang benar."],["Apa perbedaan completeness dan validity?","Completeness mengukur apakah field wajib tersedia; validity memeriksa apakah nilainya memenuhi format/range/rules yang benar."]],[["Data lineage","Jejak source dan transformasi data."],["Grain","Level detail setiap record."],["Data quality","Akurasi, completeness, consistency, uniqueness, validity, and timeliness."]]),
  makeRoleChapter("GA4, native platform analytics, CM360, and backend data answer different questions. GA4 event model records website/app interactions; platform dashboards apply their own attribution and identity rules; CM360 connects ad serving and Floodlight; backend systems are often closer to paid orders/revenue. Reconcile definitions and windows before combining outputs.","SIMULASI — Meta reports 120 purchases, GA4 95 purchase sessions, backend 104 paid orders. The difference may come from identity, consent, attribution, refunds, event timing, duplicate, or view-through rules. None is automatically 'the one true number' for every question.",["Map the same conversion across each system and define event/status.","Compare timestamp, timezone, source, identity, window, counting, refunds, and deduplication.","Select source of truth per decision (billing, site behavior, platform optimisation, finance).","Document what each source can and cannot answer."],"Buat source-of-truth matrix for impressions/clicks, sessions, purchase events, paid orders, revenue, and refunds. Reconcile one synthetic week and explain variances by definition.",[["Mengapa platform ads dan GA4 melaporkan conversion berbeda?","Attribution window/model, identity, timezone, consent, click/view rule, event definitions, deduplication, and processing latency dapat berbeda."],["Kapan backend order system lebih tepat untuk sales reconciliation?","Saat keputusan membutuhkan paid order, payment status, cancellation, refund, and net revenue according to finance definitions."],["Apakah GA4 purchase events otomatis sama dengan paid orders?","Tidak. Event dapat terkirim sebelum payment success, terduplikasi, dibatalkan, atau tidak membawa status/refund. Definisikan conversion stage yang dibandingkan."]],[["Native analytics","Reporting bawaan sebuah advertising/commerce platform."],["Backend source of truth","Sistem operasional yang menjadi rujukan transaksi/status bisnis."],["Floodlight","Conversion activity tracking dalam CM360."]]),
  makeRoleChapter("Spreadsheets are useful for quick validation and small analyses; SQL supports repeatable querying on larger structured data. The analyst must understand SELECT, WHERE, GROUP BY, JOIN, CASE, CTE, window functions, and aggregation traps. BigQuery Sandbox/demo data offers practice, but real exports may contain different schema, permissions, and cost considerations.","SIMULASI — spend is daily by campaign, but orders are at order-line grain. Joining directly on date/campaign multiplies spend by the number of orders. Aggregate each table to matching grain or use a valid bridge/key before joining.",["Validate a spreadsheet with control totals, filters, formulas, and duplicate checks.","Write SELECT/WHERE/GROUP BY queries for campaign-day summaries.","Use JOIN carefully; validate one-to-one/one-to-many relationships and row counts.","Use CTE/window functions for ranking, moving averages, and cohort-style comparisons."],"Buat SQL workbook/notebook with five queries: spend by campaign-day, CTR/CPC/CVR by channel, top search/creative segments, weekly pacing, and conversion cohort. Include query, expected grain, result validation, and synthetic data label.",[["Mengapa join dapat menggandakan spend?","Jika campaign-day spend row bergabung dengan beberapa order rows, spend terulang pada tiap matching order. Aggregate or join with correct key/grain."],["Kapan spreadsheet tidak lagi cukup?","Saat data besar, repeatability, multi-table transformations, auditability, or scheduled workflows require SQL/data pipelines. Spreadsheet tetap berguna untuk inspection and communication."],["Apa yang harus diperiksa setelah menjalankan query?","Row counts, nulls, distinct keys, control totals, date range, filters, and sample records against source."]],[["SQL","Bahasa query untuk data terstruktur."],["JOIN","Operasi menggabungkan tabel berdasarkan key."],["Window function","Perhitungan antarbaris dalam window tanpa mereduksi grain seperti GROUP BY."]]),
  makeRoleChapter("Dashboard harus menjawab keputusan, bukan memajang semua metrik. Pilih audience pengguna, key questions, metric hierarchy, grain, filters, dimensions, refresh cadence, and data freshness. Visualisasi harus menunjukkan comparison, trend, distribution, and anomaly without misleading scale. Add data notes and metric definitions; dashboards are operational products that need QA and ownership.","SIMULASI — executive dashboard shows 40 charts but no clear answer about why sales fell. Redesign into one business outcome page, driver breakdown, channel diagnostic, cohort/quality view, and clearly stated caveats.",["Define dashboard users and the decisions they make.","Create metric dictionary and data model before charting.","Choose visualisations appropriate to comparison, trend, distribution, and composition.","Add freshness, filters, source, definitions, and QA tests."],"Buat Looker Studio/Power BI dashboard dari dataset sintetis: executive summary, spend/pacing, funnel, channel comparison, creative/keyword, and data quality. Include metric dictionary and two decision notes.",[["Apa perbedaan dashboard operasional dengan executive dashboard?","Operational views support daily troubleshooting and granular control; executive views summarise outcomes, drivers, risk, and decisions at appropriate grain."],["Mengapa metric dictionary perlu disertakan?","Agar stakeholders memahami formula, unit, window, source, and limitations; mencegah dua pihak memakai nama metric dengan definisi berbeda."],["Apa risiko dual-axis atau truncated axis tanpa penjelasan?","Visual can exaggerate or hide differences and imply relationships not supported by data. Use explicit scales and annotate."]],[["Data freshness","Jarak antara kejadian/source update dan dashboard update."],["Data model","Struktur tabel/relasi yang mendukung analysis."],["Metric dictionary","Definisi, formula, unit, source, owner, and limitations."]]),
  makeRoleChapter("Descriptive analysis summarises what happened; diagnostic analysis examines why. Segment results by channel, campaign, audience, creative, placement, device, geography, product, and period—but preserve sample size and comparability. Trend and decomposition are useful for hypotheses, not automatic causality. An analyst should identify the next test or evidence required before claiming a root cause.","SIMULASI — CTR rises but qualified leads fall. Creative curiosity may increase clicks while attracting low-intent users; alternatively, form errors or sales follow-up may change. Segment funnel by source, device, creative, form, and qualification status.",["Create baseline and comparable period/segment.","Break KPI into drivers (spend, impressions, clicks, CVR, AOV, qualification, margin).","Check mix shifts, seasonality, outliers, tracking, and operational changes.","Write multiple hypotheses and rank by evidence/confidence/impact."],"Buat diagnostic memo for one synthetic performance change. Show baseline/current, decomposition, segments, evidence, competing hypotheses, additional data needed, and recommended next step.",[["Mengapa korelasi antara spend dan sales tidak membuktikan causality?","Spend may increase when demand is already expected to rise; seasonality, promotions, and other variables also affect sales. A causal design is required."],["Apa pentingnya segment size saat membaca perubahan CVR?","Small or changing samples create volatile rates and compositional effects. Report denominators and confidence, not percentage alone."],["Bagaimana membedakan finding dengan hypothesis?","Finding is directly supported by analysis; hypothesis proposes a mechanism that still needs validation. Label each separately."]],[["Decomposition","Menguraikan outcome ke driver penyusunnya."],["Mix shift","Perubahan proporsi antarsegmen yang memengaruhi aggregate metric."],["Outlier","Observasi yang jauh dari pola umum dan perlu diperiksa."]]),
  makeRoleChapter("Attribution assigns credit to touchpoints under a chosen model and window; incrementality estimates additional outcomes caused by marketing. They are different questions. Last-click, data-driven attribution, MMM, and experiments each have assumptions, data requirements, and blind spots. Marketing effectiveness combines observed outcome with design quality and causal confidence.","SIMULASI — Meta reports high attributed ROAS, but a geo-holdout shows much smaller incremental lift. The gap can reflect existing demand capture, organic cannibalisation, overlap, view-through attribution, or measurement design. Do not simply select the biggest platform-reported number.",["Define the question: credit allocation or causal lift?","Document attribution model, windows, identity, channel coverage, and data gaps.","Evaluate holdout/geo experiment assumptions, balance, contamination, and seasonality.","Explain uncertainty and do not compare model outputs as if they were the same metric."],"Buat attribution comparison memo for two models and design a geo-holdout concept: randomisation unit, treatment/control, pre-period, outcome, guardrails, sample/geo suitability, contamination risks, and decision rule.",[["Apa yang dijawab attribution dan incrementality?","Attribution allocates credit; incrementality estimates the additional outcome caused by activity beyond what would have happened anyway."],["Mengapa last-click dapat undervalue awareness?","It credits the final observed click and may ignore earlier touchpoints that influenced discovery or consideration."],["Apa risiko geo-holdout?","Geo imbalance, cross-border spillover, insufficient markets, seasonality, other regional changes, and contamination can bias the estimate."]],[["Attribution window","Rentang waktu yang menentukan eligibility credit."],["Holdout","Group deliberately not exposed/treated for comparison."],["Causal inference","Metode untuk mengestimasi efek suatu treatment/intervention."]]),
  makeRoleChapter("Experiment design tests a hypothesis under controlled conditions. Define treatment, control, randomisation unit, primary metric, guardrails, minimum detectable effect, sample size, duration, stopping rule, and contamination risk before launch. Statistical significance is not practical significance; a statistically detectable lift may not create commercial value, and an inconclusive result is not proof of equality.","SIMULASI — a landing-page experiment has 1,000 sessions per arm and small conversion difference. Without pre-defined sample size/power and fixed decision rule, repeatedly checking results can inflate false positive risk.",["Translate observation into a falsifiable hypothesis.","Select randomisation unit and ensure treatment assignment stays stable.","Define primary metric, guardrails, MDE, sample/duration, and stopping criteria.","Check sample balance, instrumentation, seasonality, and segment effects before interpreting."],"Buat A/B testing protocol: hypothesis, control/treatment, eligible population, randomisation, primary/secondary/guardrail metric, sample assumption, duration, stopping, QA, and decision rules. Use a calculator with stated assumptions.",[["Apa arti p-value/statistical significance?","It describes how compatible data are with a null model under assumptions; it is not the probability that the hypothesis is true or the size of business impact."],["Mengapa primary metric ditentukan sebelum experiment?","To reduce selective interpretation and p-hacking. A pre-specified metric anchors the decision."],["Apa arti inconclusive result?","Evidence has not reached the decision threshold. It does not demonstrate that variants are identical; investigate power, variance, sample, and execution."]],[["Randomisation unit","Unit yang diacak, misalnya user, session, account, or geo."],["MDE","Minimum Detectable Effect."],["Power","Probabilitas mendeteksi effect tertentu jika effect itu benar ada, under assumptions."]]),
  makeRoleChapter("Insight storytelling turns analysis into a clear decision. Strong insight contains observation, evidence, interpretation, recommendation, impact, confidence, and limitation. It answers why the finding matters, what action should happen, who owns it, and how it will be validated. Executive communication is selective—not a dump of every chart.","SIMULASI — dashboard flags campaign underperformance. The analyst recommends creative refresh and landing-page QA, explains evidence by device/creative, states tracking confidence, estimates downside risk, and requests a controlled test rather than increasing budget indiscriminately.",["Write headline as a finding, not a vague topic.","Show evidence and comparison needed to support the finding.","State recommendation, expected impact, confidence, and limitation.","Define owner, due date, and measurement of next action."],"Buat five-part insight memo: what changed, why it may have changed, supporting data, recommended action, and risk/limitation. Convert it into a 5-minute executive slide with one primary chart.",[["Apa yang membedakan insight dari data point?","Insight connects evidence to a meaningful explanation or decision implication; a data point is simply a measurement."],["Mengapa limitation harus disampaikan?","To prevent overclaiming and help stakeholders understand where more evidence or validation is required."],["Apa isi rekomendasi yang actionable?","Specific action, owner, timing, expected outcome, guardrail, and validation plan."]],[["Executive narrative","Penyampaian temuan yang menekankan keputusan dan implikasi."],["Confidence","Tingkat keyakinan berdasarkan kualitas dan konsistensi evidence."],["Limitation","Batas data, method, or inference that changes interpretation."]]),
  makeRoleChapter("Capstone role 10 menggabungkan reporting dan measurement pathway, tetapi advanced modelling remains a separate learning depth. A Media Analytics portfolio should show dashboard, data QA, diagnostic memo, and stakeholder recommendation. A Marketing Science pathway can add regression, experiment, MMM introduction, or model-validation notebook when statistics/data foundation allows; never label a simple spreadsheet as professional MMM.","SIMULASI — consumer brand has 12-month media, search, sales, promo, and price data. Participant creates clean data model, dashboard, diagnostic analysis, and a cautious recommendation. Advanced optional: fit a small regression and discuss endogeneity/seasonality limits.",["Select the pathway depth based on role target and quantitative prerequisites.","Build a repeatable data cleaning and KPI model.","Deliver dashboard, diagnosis, recommendation, and optional statistical analysis.","Document data limitations, validation checks, and what the model cannot prove."],"Buat capstone pack: source map, data-quality audit, KPI workbook, SQL queries, dashboard, diagnostic memo, attribution/experiment note, executive deck. Advanced elective: regression/Robyn/Google Meridian learning notebook with methodology, validation, and limitations; label synthetic.",[["Mengapa Media Analytics dan Marketing Science tidak boleh disamakan kedalamannya?","Media Analytics core is descriptive/diagnostic reporting and recommendations; Marketing Science requires stronger statistics, causal reasoning, modelling, and validation."],["Apa yang harus ditulis saat membuat modelling exercise dari data sintetis?","Dataset label, assumptions, method, model design, validation, error metrics, limitations, and no claim of actual client impact."],["Apa yang perlu diuji sebelum memakai model untuk budget allocation?","Out-of-sample validity, sensitivity, stability, causal assumptions, data coverage, collinearity/endogeneity, and business plausibility."]],[["Regression","Metode statistik untuk memodelkan hubungan antara variables."],["MMM","Marketing Mix Modeling."],["Model validation","Pemeriksaan performance/stability against data and assumptions."]])
 ]
};
ROLE_GUIDES.seo = {
 scope:"SEO Specialist meningkatkan organic search visibility dan qualified organic traffic melalui technical SEO, keyword/search intent, content, off-page authority, and measurement. GEO/AEO menjadi emerging orientation, bukan profesi terpisah yang menjanjikan citation. Google secara eksplisit menyatakan fundamental SEO tetap relevan untuk AI features dan tidak ada special markup/optimization wajib.",
 workflow:["<b>Understand search demand.</b> Analisis audience intent, SERP, competitors, and category topics.","<b>Audit technical foundations.</b> Crawling, indexing, architecture, canonical, JavaScript, performance, and structured data.","<b>Improve content and authority.</b> On-page relevance, helpful content, internal linking, digital PR/backlinks, and content maintenance.","<b>Measure organic performance.</b> GSC/GA4, query/page segmentation, technical errors, and business contribution.","<b>Monitor emerging search.</b> Track AI-search visibility as exploratory evidence, not guaranteed placement."],
 qa:["Search intent lebih penting daripada keyword stuffing. Content harus membantu user, menyelesaikan kebutuhan, and be discoverable; technical fixes only help if they address actual crawl/index/user issues.","Google's AI search guidance says existing SEO best practices apply and there is no special AI markup or extra requirement for AI Overviews/AI Mode. Never promise AI citation/ranking through GEO hacks.","Prioritise technical SEO by impact, evidence, affected URLs, effort, dependencies, and business value. A crawl issue is not automatically a traffic issue; verify indexing, rendering, and query/page performance."],
 glossary:[["Crawlability","Kemampuan crawler menemukan dan mengakses URL."],["Indexability","Kelayakan halaman untuk masuk index."],["Canonical","Hint untuk memilih preferred URL."],["Robots.txt","Aturan crawling; bukan kontrol privasi."],["XML sitemap","Daftar URL yang ingin diinformasikan ke search engine."],["Core Web Vitals","Metrik pengalaman page: loading, interactivity, visual stability."],["Structured data","Markup terstruktur untuk membantu search engine memahami konten."],["Search intent","Kebutuhan di balik query."],["Topical cluster","Kelompok konten yang saling terhubung pada satu topik."],["GEO/AEO","Emerging practices for discoverability in generative/answer engines; no guarantee."]],
 chapters:[
  makeRoleChapter("SEO begins with how search engines discover, crawl, render, index, and rank content, and how users express needs through queries. Organic visibility includes classic search results, local results, image/video surfaces, and AI-assisted search features. Role SEO is not the same as paid search; it improves eligibility and usefulness of owned content over time.","SIMULASI — brand sees traffic drop after site redesign. Before rewriting content, check robots directives, canonical mapping, redirects, rendering, index coverage, and page/query performance. The root cause may be technical, not content relevance.",["Map search engine stages: discovery, crawl, render, index, retrieval/ranking, and SERP presentation.","Define organic visibility, qualified traffic, conversions, and business value.","Audit site/search properties and document baseline/known limitations."],"Buat search ecosystem map plus baseline: business/website context, audience intent, organic KPIs, search properties, crawl/index signals, and three hypotheses for improvement.",[["Apa perbedaan crawling dan indexing?","Crawling is fetching/discovering a URL; indexing is storing/understanding content for possible retrieval. A crawled URL is not guaranteed indexed."],["Mengapa ranking bukan satu-satunya KPI SEO?","Qualified clicks, relevance, conversions, assisted journey, brand visibility, and business value may matter more than one position metric."],["Mengapa SEO dan paid search harus dibedakan?","SEO improves organic discoverability of owned content; paid search buys eligible ad placements based on auction and budget. Their levers, costs, and measurement differ."]],[["Crawling","Proses menemukan/mengambil URL."],["Indexing","Proses memasukkan/memahami konten dalam index."],["SERP","Search Engine Results Page."]]),
  makeRoleChapter("Keyword and topic research discovers what users seek, how competitive results behave, and which pages should satisfy each intent. Evaluate query, modifiers, seasonality, location, SERP features, intent, volume estimate, relevance, commercial value, and content opportunity. Competitor research should analyse competing pages and topic coverage, not blindly copy competitor keywords.","SIMULASI — a site targets one broad term with a generic homepage while users ask specific comparison, price, and troubleshooting questions. Topic mapping reveals distinct pages/intents and prevents cannibalisation.",["Collect seed topics from Search Console, customer questions, search tools, and SERP.","Classify intent and SERP format by query cluster.","Map one primary page per intent and identify content gaps/cannibalisation.","Prioritise by relevance, opportunity, effort, and evidence."],"Buat keyword/topic map with 30–50 queries, intent, SERP feature, cluster, target URL, competitor page, volume source/period, priority, and content gap.",[["Apa risiko mengejar search volume tinggi tanpa intent match?","The page may attract the wrong audience and fail to satisfy the query, creating poor engagement/conversion and wasted content effort."],["Apa itu keyword cannibalisation?","Multiple pages compete for similar intent/query, making it unclear which URL best satisfies searchers; assess whether pages serve distinct needs before merging."],["Mengapa SERP harus diperiksa langsung?","Search features, result types, local intent, and competitor formats reveal what the engine considers useful for that query."]],[["Keyword cluster","Kelompok query yang memiliki intent/topic serupa."],["Cannibalisation","Overlap page intents that can compete for the same queries."],["SERP feature","Special result type such as local pack, video, image, or AI feature."]]),
  makeRoleChapter("Website architecture affects discoverability, hierarchy, internal links, and crawl paths. Audit URL patterns, navigation, orphan pages, parameters, pagination, canonical hints, redirects, robots, sitemap, and duplicate content. Robots.txt controls crawling, not confidentiality; noindex/canonical/redirect have different semantics and must be used correctly.","SIMULASI — faceted category filters create 100,000 parameter URLs, crawl resources are wasted, and canonical signals conflict. Plan a crawlable architecture with controlled parameters and canonical strategy.",["Crawl site and segment by template, status, depth, and indexability.","Inspect robots.txt, sitemap, canonicals, redirects, noindex, and parameter handling.","Find orphan/deep pages and internal-link gaps.","Prioritise fixes with developers and define acceptance tests."],"Buat technical architecture audit: URL sample, crawl status, canonical/redirect rules, robots/sitemap, internal-link depth, duplicates, impact, owner, and dev ticket/QA plan.",[["Apakah robots.txt dapat melindungi private content?","No. It can discourage crawling but does not secure content; use authentication/access control for private material."],["Apa perbedaan canonical dan redirect?","Canonical is a consolidation hint; redirect sends users/crawlers to another URL. They are not interchangeable."],["Mengapa sitemap tidak menjamin indexing?","It provides discovery information, but search engines choose what to index based on quality, accessibility, canonicalization, and other signals."]],[["Canonical","Hint URL pilihan untuk konsolidasi."],["Orphan page","Page tanpa internal links yang membantu discovery."],["Redirect","Instruksi untuk mengirim user/crawler ke URL lain."]]),
  makeRoleChapter("Technical SEO covers rendering, indexation, performance, mobile access, JavaScript, and structured data. Core Web Vitals are user-experience diagnostics, not guaranteed ranking levers in isolation. Validate rendered HTML, mobile behavior, page templates, response codes, and structured-data consistency. Schema must describe visible content and does not guarantee rich results or AI citation.","SIMULASI — product pages are rendered by client-side JavaScript and search engine rendering misses product content due to API error. A crawl of raw HTML looks empty; rendered inspection and logs reveal the issue.",["Inspect CWV/Lighthouse/PageSpeed by representative templates and field/lab data.","Test mobile rendering, JavaScript output, internal resources, status codes, and structured data.","Document template-level defects, affected URL count, user impact, and release tests.","Coordinate with engineering; verify changes in staging and after deployment."],"Buat technical SEO report for five templates: CWV evidence, rendering/indexability, schema validity, mobile/accessibility, issue severity, dev ticket, before/after QA, and limitations.",[["Apakah skor Lighthouse menjamin ranking naik?","No. Lab metrics diagnose issues; ranking and user outcomes depend on many signals, real-user context, competition, and relevance."],["Apa yang harus dilakukan bila JS content tidak muncul pada rendered page?","Inspect rendering/network/API errors, server-side rendering/prerender strategy, blocked resources, and internal logs; test a representative URL after fix."],["Apakah schema menjamin rich result atau AI citation?","No. Eligibility and display are controlled by search engines; structured data must accurately describe visible content and does not guarantee display/citation."]],[["Core Web Vitals","Metrics for loading, interaction, and visual stability."],["JavaScript SEO","SEO work on rendering/discovery/indexing of JS-powered content."],["Structured data","Machine-readable markup describing page entities/content."]]),
  makeRoleChapter("On-page SEO aligns page content with search intent and makes information understandable. Optimise title, heading, copy, internal links, image alt where meaningful, product attributes, and schema where applicable. Do not stuff keywords, create doorway pages, or generate scaled unhelpful content. Content accuracy, expertise, source, update quality, and page purpose should be explicit.","SIMULASI — article has a target keyword repeated unnaturally but misses the actual comparison criteria users need. Rewrite with clear answer, evidence, structure, examples, and next action.",["Audit page intent, content completeness, originality, accuracy, and competing pages.","Optimise titles/headings, key answers, internal links, media, and page experience.","Use structured data only when supported by visible page content and current guidelines.","Plan refresh/update ownership for changing facts."],"Optimise five pages: before/after title, headings, content outline, internal links, media, structured data where applicable, evidence sources, CTA, and expected user benefit.",[["Mengapa keyword stuffing adalah praktik buruk?","It degrades usefulness and may violate spam policies; content should satisfy the query rather than repeat words."],["Apa peran internal link?","It helps users and crawlers discover related pages and understand site structure; link anchors should describe destination accurately."],["Kapan content perlu di-refresh?","When facts, product, search intent, policy, availability, or competing information materially changes—not simply to change a date."]],[["On-page SEO","Optimasi elemen/isi pada halaman."],["Internal link","Link dari satu halaman ke halaman lain dalam website."],["Helpful content","Content primarily created to help the intended audience."]]),
  makeRoleChapter("Off-page SEO evaluates reputation and relevant external references. Backlinks are not interchangeable votes; relevance, editorial context, quality, authenticity, and policy compliance matter. Digital PR builds newsworthy content/relationships that may earn coverage and links. Avoid paid-link schemes, link farms, or automated spam.","SIMULASI — vendor proposes 500 backlinks from unrelated sites. Short-term link counts rise, but links add no audience value and create spam risk. A smaller digital PR plan with relevant publisher coverage is more defensible.",["Audit backlink profile, referring domains, link context, anchors, and suspicious patterns.","Assess competitor coverage and linkable assets.","Develop digital PR/story angles with evidence, spokesperson, and outreach process.","Record permission/disclosure and policy compliance."],"Buat backlink/authority assessment: sample links, topical relevance, source quality, anchor patterns, competitor gap, digital PR opportunity, risk, and action plan.",[["Mengapa jumlah backlink bukan ukuran tunggal authority?","Link relevance, context, editorial legitimacy, and policy compliance matter; raw counts can be manipulated."],["Apa peran digital PR dalam SEO?","It can earn relevant coverage/mentions and support brand credibility, though links or rankings are not guaranteed."],["Haruskah semua toxic-looking links langsung didisavow?","No. Verify patterns and impact; use search-engine guidance and avoid disavowing based solely on third-party toxicity scores."]],[["Referring domain","Domain yang memberi link ke website."],["Anchor text","Teks yang dapat diklik pada hyperlink."],["Digital PR","Aktivitas hubungan media/publication untuk membangun coverage/reputasi."]]),
  makeRoleChapter("Local SEO helps businesses appear for geographically relevant searches. Core work includes Google Business Profile accuracy, category, hours, address/service area, reviews, local landing pages, local links/citations, and NAP consistency. Avoid fake locations and review manipulation; local relevance/prominence/proximity signals have limits and market-specific context.","SIMULASI — clinic has duplicate business profiles and mismatched opening hours. Searchers visit when closed and reviews fall. Profile governance and accurate local information are higher priority than more keywords.",["Audit Google Business Profile eligibility, ownership, category, address/service area, hours, and attributes.","Check NAP consistency, duplicate profiles, reviews, and local landing pages.","Map local query intent, service area, and location-page content.","Set review response and update governance."],"Buat local SEO checklist for one business: GBP, categories, service area, location pages, NAP, review policy, local intent, tracking, and ownership. Optional extension: international hreflang/site structure scenario.",[["Apa risiko membuat fake business locations?","It misrepresents physical presence, may violate platform guidelines, and damages trust and eligibility."],["Apa yang harus diperhatikan saat meminta review?","Use neutral compliant requests; do not buy reviews, gate negative reviews, or incentivise only positive feedback."],["Apa bedanya local landing page dan doorway page?","A useful location page provides genuinely distinct local information/services; doorway pages are near-duplicate pages made primarily to rank."]],[["NAP","Name, Address, Phone consistency."],["GBP","Google Business Profile."],["Hreflang","Signal for language/region variants of pages."]]),
  makeRoleChapter("GSC and GA4 provide complementary views: Search Console shows search performance/indexing signals; GA4 shows measured website/app activity after a visit. Analyse query/page/device/country, clicks/impressions/CTR/position, landing behavior, conversion, and revenue definitions. Average position is aggregated and cannot explain every ranking situation; query data may be anonymised/limited.","SIMULASI — clicks fall although impressions rise. SERP feature changes, CTR, query mix, country/device, seasonality, or indexing may explain it. Compare pages and query segments before recommending content rewrite.",["Define organic KPIs and their sources/definitions.","Join GSC and GA4 carefully at page/date grain; handle query/page mismatch and data thresholds.","Build page/query cohorts and technical alerts.","Write insight with evidence, seasonality, and measurement caveats."],"Buat organic dashboard using GSC + GA4 demo/export: clicks, impressions, CTR, average position, landing sessions, conversion, and key page groups. Add data freshness and metric definitions.",[["Mengapa GSC clicks tidak sama dengan GA4 organic sessions?","Different counting, identity, consent, filtering, session rules, timezone, and query sampling can create differences."],["Apa arti average position?","An aggregate position measure across queries/impressions; it is not one fixed rank for every user or query."],["Bagaimana mencegah false diagnosis saat clicks drop?","Segment by page/query/device/country, inspect indexation and SERP changes, compare periods, and check tracking/data freshness."]],[["Search Console","Google tool for search performance and indexing insights."],["Organic session","Measured visit attributed to organic source under analytics rules."],["CTR","Clicks divided by impressions."]]),
  makeRoleChapter("AI Overviews, answer engines, and generative search change how information may be surfaced, but Google says foundational SEO practices remain applicable and there is no special markup or extra requirement for AI features. GEO/AEO is an emerging monitoring/strategy layer: improve helpful source content, entities, clarity, technical accessibility, author expertise, and measurement. Never promise guaranteed AI citations or rankings.","SIMULASI — brand wants to be cited by AI answers. Team creates an AI visibility baseline with date, platform, prompt/query, cited source, context, and share of observed mentions. It does not assume a particular schema, llms.txt, or mention trick guarantees results.",["Read official AI-search guidance and separate confirmed guidance from vendor speculation.","Create controlled prompt/query sets by audience question and intent.","Log mentions, citations, source URLs, correctness, and context over time.","Improve source quality, evidence, entities, and site fundamentals; validate changes."],"Buat GEO/AEO baseline with 20 prompts, multiple AI/search platforms, date, prompt, brand mention, citation URL, context, factual accuracy, and next action. Explicitly label methodology limitations and no guarantee.",[["Apakah ada markup khusus yang wajib agar muncul di AI Overviews?","Google says no additional technical requirement or special markup is needed beyond SEO fundamentals; eligibility/citation is not guaranteed."],["Mengapa AI visibility monitoring harus mencatat prompt/date/platform?","Outputs change with prompts, model, location, and time; consistent logs are needed for directional comparison."],["Apa yang harus dihindari pada GEO/AEO?","Guaranteed ranking/citation claims, fabricated mentions, keyword/markup hacks, or tactics unsupported by official guidance."]],[["GEO","Generative Engine Optimization, an emerging term for visibility in generative systems."],["AEO","Answer Engine Optimization."],["AI visibility log","Record of AI search prompts, mentions, citations, and context."]]),
  makeRoleChapter("SEO capstone connects audit, intent, technical structure, content, off-page, local/e-commerce considerations, measurement, and emerging AI-search monitoring. Prioritise fixes with impact/evidence/effort/dependency; specify dev/content owners and 30/60/90-day milestones. A good audit includes no unsupported promises and clearly separates search-engine guidance from experimentation hypotheses.","SIMULASI — Indonesian retailer wants more qualified organic traffic across category and product pages. Audit identifies crawling duplication, weak category content, poor internal links, and product schema issues. Priorities differ by affected template and commercial value.",["Synthesize technical, keyword, content, authority, local/e-commerce, and measurement audits.","Prioritise tickets by impact, affected URLs, confidence, effort, and dependencies.","Create roadmap with owners, acceptance criteria, and measurement baseline.","Prepare executive explanation and limitations."],"Buat portfolio SEO pack: technical audit, keyword/topic map, five-page content plan, on-page examples, backlink/PR assessment, GSC/GA4 dashboard, AI visibility baseline, and 90-day roadmap.",[["Bagaimana memprioritaskan issue SEO?","Use affected pages, user/search impact, evidence, business value, effort, and dependency—not just tool severity scores."],["Apa yang wajib diberi acceptance criteria?","Concrete expected state, affected URLs/templates, test method, owner, and evidence after deployment."],["Mengapa capstone harus menyebut limitation?","SEO outcomes depend on competition, engine changes, site releases, seasonality, and external factors; transparency avoids overclaiming."]],[["SEO roadmap","Prioritised plan for technical/content/authority work."],["Acceptance criteria","Observable conditions that must be met to approve a change."],["Search visibility","How often/where content appears in search experiences."]])
 ]
};
ROLE_GUIDES.crm = {
 scope:"CRM/Lifecycle/Marketing Automation mengelola relationship dan komunikasi dari lead sampai retention/reactivation. Role ini menghubungkan customer data, identity, segmentation, triggers, journeys, email/WhatsApp/SMS/push, automation architecture, consent, deliverability, experimentation, and lifecycle economics. Jangan menyamakan CRM strategy dengan sekadar mengoperasikan satu software.",
 workflow:["<b>Understand lifecycle and business model.</b> Define customer stages, value, purchase cycle, and outcomes.","<b>Design reliable data.</b> Map identifiers, events, consent, preference, data quality, and source of truth.","<b>Build segments and journeys.</b> Define eligibility, trigger, content, timing, frequency, suppression, and exit.","<b>Operate safely.</b> Test flows, deliverability, channel policy, opt-out, monitoring, and customer care handoff.","<b>Measure lifecycle value.</b> Activation, repeat purchase, retention, churn, contribution, complaint, and incremental lift."],
 qa:["Contact data is not automatically marketing consent. Verify collection purpose, consent/legal basis, preference, suppression, channel-specific rules, and records before sending promotional messages.","Automation must have eligibility, trigger, branch, frequency cap, suppression, exit condition, error handling, data freshness, duplicate protection, and owner. Test opt-out and missing-data paths.","Lifecycle performance should be read with cohorts, contribution/margin, unsubscribe, complaint, and customer experience. More sends or higher open rate do not automatically mean business improvement."],
 glossary:[["Lifecycle stage","Tahap hubungan customer dari acquisition sampai loyal/reactivation."],["Trigger","Event/condition that starts a journey."],["Suppression","Rule that excludes contacts from communication."],["Frequency cap","Batas intensitas komunikasi per periode."],["Deliverability","Kemampuan pesan mencapai inbox/destination sesuai kebijakan."],["Preference centre","Tempat customer mengatur channel/topic preferences."],["Cohort","Kelompok customer dengan titik awal/karakteristik yang sama."],["Churn","Berhentinya hubungan/aktivitas berdasarkan definisi bisnis."],["Lead scoring","Model penilaian lead berdasarkan fit/intent/behavior."],["CDP","Customer Data Platform; unify profiles/events under permissions and data governance."]],
 chapters:[
  makeRoleChapter("CRM is a strategy and operating system for managing customer relationships—not simply a contact database or vendor tool. Lifecycle maps acquisition, lead nurture, conversion, onboarding, activation, repeat, loyalty, lapse, and reactivation. Stage definitions must be based on observed business behavior and customer value.","SIMULASI — an ecommerce brand treats every email subscriber as a lead, even if they have purchased multiple times. Lifecycle stage is wrong, so they receive acquisition offers instead of onboarding/replenishment messages.",["Define stages by observable events and business meaning.","Map customer questions, barriers, value moments, and service needs at each stage.","Select outcomes: activation, repeat, retention, contribution, churn, and experience.","Identify which interactions should be human-led vs automated."],"Buat lifecycle strategy one-pager: stages, entry/exit definitions, goals, key customer questions, triggers, channels, metrics, owners, and risks.",[["Mengapa CRM bukan sekadar software?","Software executes workflows; CRM strategy defines customer stages, value, data, communication rules, ownership, and outcomes."],["Mengapa lifecycle stage harus berbasis event/criteria?","Without observable entry/exit rules, segments overlap and communication becomes inconsistent."],["Apa beda acquisition dengan activation?","Acquisition gains a new contact/customer; activation helps them reach first meaningful value/action."]],[["Lifecycle","Tahap hubungan customer."],["Activation","First meaningful value/action after acquisition."],["Reactivation","Mengajak kembali customer yang lapse/inactive."]]),
  makeRoleChapter("A reliable CRM data architecture defines identifiers, profiles, events, attributes, preferences, consent, deduplication, retention, and system ownership. CRM platform, ecommerce, POS, web analytics, support, and CDP may carry inconsistent records. Data minimisation and lawful purpose should shape design from the start.","SIMULASI — a person signs up twice with different email casing and one phone number; orders live in ecommerce, preferences in CRM. Poor identity resolution creates duplicate sends and false LTV.",["Map systems, data owners, identifiers, events, profile fields, and refresh cadence.","Define identity matching and duplicate resolution rules.","Document consent source, purpose, retention, access, and deletion/opt-out handling.","Separate mandatory service messages from promotional eligibility according to policy/law."],"Buat customer data map and consent flow: systems, keys, events, profile fields, source of truth, duplicate rules, preference, retention, access, and deletion/opt-out scenarios.",[["Mengapa email/phone belum tentu unique person ID?","A person may share contacts, change identifiers, or have duplicates; identity resolution needs explicit rules and confidence."],["Mengapa consent provenance perlu disimpan?","To demonstrate when, how, for what purpose, and on which channel a contact agreed or objected."],["Apa risiko over-collecting data?","Higher security/privacy risk and processing burden without justified value; collect only data necessary for stated purpose."]],[["Identity resolution","Proses menghubungkan records ke profile."],["Deduplication","Penanganan record/event duplikat."],["Data minimisation","Membatasi data pada kebutuhan yang sah/relevan."]]),
  makeRoleChapter("Segmentation should be actionable, explainable, stable, and permitted. Use recency, frequency, monetary value, product/category, lifecycle event, behavior, propensity, and service status. Lead scoring may combine fit and intent but must be validated against outcome; never treat a score as objective truth without checking bias and data quality.","SIMULASI — high email opens are used as the only high-intent signal, but automated privacy/proxy opens inflate the segment. Qualification should include meaningful clicks, form data, product actions, and sales outcomes.",["Choose segment purpose and definition before selecting fields.","Create stage and audience criteria with inclusion/exclusion logic.","Design scoring rules and check predictive validity, bias, and missing data.","Ensure segments are large enough and can be activated in channels."],"Buat 3 segment and one lead-score model: fit, intent, recency, behavior, exclusions, consent, score rule, threshold, validation outcome, and owner.",[["Mengapa opens tidak selalu sinyal intent yang kuat?","Privacy protection and automated image loading can inflate opens; use a broader set of meaningful actions and sales outcomes."],["Apa beda fit score dan intent score?","Fit estimates whether a contact matches target profile; intent estimates observable interest or readiness."],["Apa yang harus diuji sebelum memakai lead scoring?","Historical predictive accuracy, calibration, bias, missing data, threshold, and whether sales follow-up capacity can support it."]],[["Segmentation","Pengelompokan contact berdasar aturan."],["Lead scoring","Penilaian fit/intent untuk prioritas follow-up."],["Propensity","Perkiraan kemungkinan melakukan outcome tertentu."]]),
  makeRoleChapter("Trigger-based communication responds to customer behavior or status. A trigger is the event/condition; a campaign is a scheduled message; a journey is a sequence with branching. Correct workflows need eligibility, timing, suppression, frequency, exit, fallback, error handling, and human handoff. Avoid sending multiple journeys that conflict.","SIMULASI — a customer starts checkout, receives a cart reminder, then purchases; the reminder still sends because purchase event does not suppress/exit the flow. Fix branch logic and event latency handling.",["Map event/condition to trigger and eligibility.","Define journey branches, delays, frequency caps, exclusions, exit conditions, and retries.","Handle duplicates, missing events, late purchase, and contact preference changes.","Document customer-care and escalation handoff."],"Buat trigger map of six events with audience, timing, message objective, channel, suppression, exit, fallback, owner, and QA scenario.",[["Apa beda trigger, campaign, dan journey?","Trigger starts a workflow; campaign is a message/activation; journey is a sequenced set of steps and branches over time."],["Mengapa exit condition wajib ada?","It prevents outdated messages after purchase, unsubscribe, service issue, or lifecycle status change."],["Apa yang harus terjadi jika purchase event terlambat?","Use robust suppression/verification windows, dedupe, and state reconciliation to avoid sending irrelevant reminders."]],[["Trigger","Event/condition that starts flow."],["Exit condition","Condition that ends journey eligibility."],["Suppression","Rule excluding a contact from a send."]]),
  makeRoleChapter("Email, WhatsApp, SMS, and push have different permission, format, utility, latency, cost, and policy rules. Channel selection should reflect customer preference and message urgency. Transactional/service messages and marketing messages need to be classified correctly; consent, opt-out, quiet hours, template approval, and platform rules must be respected.","SIMULASI — a brand uses WhatsApp promotional templates for all order updates; customer complains and blocks the account. Separate transactional updates from promotional campaigns and honour channel preference/opt-out.",["Create message-channel matrix by purpose, urgency, customer preference, and policy.","Check official WhatsApp/email/SMS/push rules, template/content requirements, and opt-out.","Set message frequency, quiet hours, content QA, and customer-care response process.","Use fallback channel only when permitted and appropriate."],"Buat channel-message matrix for Email, WhatsApp, SMS, and Push: message purpose, eligibility, consent, format, frequency, opt-out, fallback, metrics, and policy source.",[["Mengapa nomor WhatsApp tidak otomatis berarti boleh promosi?","Having a phone number is not the same as marketing permission; use channel-specific consent/legal basis and honour opt-out."],["Mengapa transactional dan promotional message harus dipisah?","They have different purpose, policy, content, and consent requirements; mixing them creates compliance and customer-trust risk."],["Bagaimana memilih channel?","Based on customer preference, urgency, usefulness, delivery reliability, cost, permission, and content suitability."]],[["Transactional message","Pesan terkait layanan/transaksi yang diminta/diharapkan."],["Marketing message","Pesan promosi atau penawaran."],["Opt-out","Pilihan untuk berhenti menerima komunikasi."]]),
  makeRoleChapter("Automation workflow architecture includes event triggers, conditions, delays, branches, actions, webhook/API, data updates, retries, error queues, and monitoring. Automation should have a clear owner and manual fallback. Tools such as HubSpot, Salesforce Marketing Cloud, Braze, and other platforms differ; teach transferable logic before vendor-specific UI.","SIMULASI — new lead fills form; CRM update fails because phone field is blank. Without fallback/retry, contact disappears. Workflow should log error, notify owner, and avoid duplicate contact creation.",["Draw workflow with entry criteria, branches, actions, delays, suppression, exit, and error routes.","Map data fields and consent into platform fields.","Design duplicate handling, retry policy, idempotency, and owner alerts.","Test happy path and failure path before publish."],"Buat two automation blueprints (new lead nurture and post-purchase onboarding) with trigger, field map, branches, delays, content, exit, consent, retries, error alert, and QA.",[["Mengapa workflow perlu error handling?","APIs/data sources fail and events may be missing/duplicated; error handling prevents silent data loss and repeated sends."],["Apa itu idempotency dalam workflow?","A repeat action should not create duplicate records/messages when the same event is processed again."],["Mengapa manual fallback tetap diperlukan?","Some customer situations require human judgement, service resolution, or recovery outside automated logic."]],[["Branch","Decision path in a workflow."],["Webhook","Event-driven message between systems."],["Idempotency","Safe repeated processing without duplicate effect."]]),
  makeRoleChapter("Personalization should use relevant permitted data and avoid creepy/inaccurate assumptions. Deliverability requires sender authentication, domain reputation, list hygiene, bounce/complaint monitoring, unsubscribe handling, and frequency balance. Message content, dynamic tokens, and fallback values must be tested; empty or stale personalization can damage trust.","SIMULASI — email template says 'Hi {{first_name}}' but missing names show blank text; purchase reminders use wrong product category. Preview and fallback rules prevent poor customer experience.",["Define personalization data, purpose, freshness, and fallback.","Configure sender authentication according to current provider guidance (SPF/DKIM/DMARC).","Monitor bounce, complaint, unsubscribe, and engagement quality.","Test rendering, dynamic content, links, and channel preference."],"Buat deliverability checklist and personalization plan: authentication, list hygiene, segment, data field, fallback, content QA, frequency, monitoring, and unsubscribe test.",[["Mengapa personalization bukan sekadar menyisipkan nama?","It must be relevant, accurate, permissioned, and useful; incorrect personalization harms trust."],["Apa peran SPF/DKIM/DMARC?","They help authenticate sender/domain and support email security/reputation; correct setup must match sending configuration."],["Metrik apa selain open rate yang perlu dipantau?","Clicks, conversion, bounce, complaint, unsubscribe, deliverability, revenue/contribution, and customer experience."]],[["SPF","Sender Policy Framework."],["DKIM","DomainKeys Identified Mail."],["DMARC","Domain-based Message Authentication, Reporting & Conformance."]]),
  makeRoleChapter("Retention, churn, cohort, and lifetime value help CRM evaluate long-term economics. Repeat purchase should be read with contribution margin, discount dependence, returns, time-to-next-order, and customer experience. Cohort analysis compares customers acquired in the same period/channel/product group; predictive churn models require validation, not just an arbitrary score.","SIMULASI — 90-day repeat rate rises after a discount campaign, but contribution per customer falls and unsubscribes increase. CRM should identify whether discount is creating healthy retention or short-term purchase pull-forward.",["Define active/retained/churned with explicit windows and product-cycle logic.","Build acquisition cohorts by month/channel/product/segment.","Calculate repeat, retention, time-to-repeat, contribution, refund, and churn signals.","Design intervention and holdout to test incremental retention effect."],"Buat cohort/retention workbook using synthetic customers: acquisition month, repeat purchase, contribution, churn definition, segment, and retention curves. Add three interventions and guardrails.",[["Mengapa cohort lebih baik daripada satu aggregate repeat rate?","Cohorts reveal differences by acquisition period/source and avoid mixing customers with different tenure."],["Apa risiko discount-heavy retention?","It can pull forward purchases and erode margin without improving long-term habit or customer value."],["Bagaimana mendefinisikan churn untuk bisnis dengan purchase cycle panjang?","Use category purchase interval and inactivity threshold validated against historical behavior, not an arbitrary universal period."]],[["Cohort","Group of customers sharing a starting period/trait."],["Retention","Proporsi customer yang tetap aktif menurut definisi."],["CLV/LTV","Customer lifetime value under stated horizon and margin assumptions."]]),
  makeRoleChapter("Lifecycle experimentation measures the effect of messages/journeys. Test subject/offer/timing/channel/branch but define randomisation, primary KPI, guardrail, sample, duration, and contact-level suppression first. Report funnel progression, not vanity opens alone; account for contact eligibility and multiple concurrent journeys.","SIMULASI — a subject-line test improves opens but reduces qualified purchases; choose the winner based on the pre-defined primary metric and guardrail, not the best looking top-funnel number.",["Define a testable lifecycle hypothesis and eligible population.","Randomise at a stable unit and ensure contacts are not in conflicting tests.","Select primary, secondary, and guardrail metrics.","Evaluate effect, uncertainty, segment differences, and downstream quality."],"Buat experiment backlog of three lifecycle tests and one full test plan with hypothesis, control/treatment, sample assumptions, primary/guardrail KPIs, duration, exclusions, and decision rule.",[["Mengapa open rate bukan selalu primary metric?","Open tracking can be noisy and doesn't guarantee customer value; select outcome tied to lifecycle objective."],["Mengapa satu contact tidak boleh masuk dua conflicting tests?","Overlapping treatments contaminate results and make attribution to each change impossible."],["Apa yang harus dilakukan jika test result inconclusive?","Review power, sample, variance, implementation, segment differences, and whether a different experiment is warranted."]],[["Holdout","Group withheld from an intervention for comparison."],["Frequency cap","Limit on how often a contact is messaged."],["Test contamination","Uncontrolled overlap between experimental treatments."]]),
  makeRoleChapter("CRM capstone must show data trust, lifecycle design, channel compliance, workflow reliability, and commercial contribution. It should include onboarding and repeat/reactivation journeys, consent/preference, data quality, failure handling, customer care handoff, measurement, and an executive recommendation. Build a prototype on sandbox/synthetic data where live permissions are unavailable.","SIMULASI — Indonesian ecommerce brand has new leads and repeat-purchase objective. Design journey from signup to first purchase, onboarding, replenishment, lapse, and opt-out. Show where humans intervene.",["Map lifecycle and customer data foundation.","Build segments and automation journey architecture.","Implement or mockup email/WhatsApp workflows with permission/suppression.","Measure activation, repeat, retention, contribution, and customer experience."],"Buat CRM capstone pack: lifecycle map, data model, consent/preferences, 3 segments, 2 journeys, message examples, workflow error handling, QA, cohort dashboard, and 90-day optimisation plan.",[["Apa yang membedakan CRM capstone yang baik dari sekadar flowchart?","It includes data, eligibility, consent, messages, operational controls, error handling, measurement, and business logic."],["Bagaimana menunjukkan automation prototype tanpa live customer data?","Use synthetic records or sandbox; label as prototype and document permissions/dependencies needed for production."],["Bagaimana menilai keberhasilan lifecycle?","Use activation, repeat, retention, contribution, churn, complaints, unsubscribe, and customer experience—not send volume alone."]],[["CRM governance","Rules for data, access, communication, and lifecycle ownership."],["Journey orchestration","Coordinating sequenced customer interactions."],["Prototype","Demonstration model, not production deployment."]])
 ]
};
